CREATE TABLE IF NOT EXISTS projects (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, location VARCHAR(200) NOT NULL, description TEXT NOT NULL, image TEXT NOT NULL, completion VARCHAR(50) NOT NULL);
CREATE TABLE IF NOT EXISTS apartments (id SERIAL PRIMARY KEY, project_id INTEGER REFERENCES projects(id), rooms INTEGER NOT NULL, area NUMERIC(6,1) NOT NULL, floor INTEGER NOT NULL, price INTEGER NOT NULL, status VARCHAR(30) DEFAULT 'available');
CREATE TABLE IF NOT EXISTS news (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, published DATE NOT NULL, image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mortgage_programs (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, rate NUMERIC(5,2) NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL, message TEXT, apartment_id INTEGER REFERENCES apartments(id), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
