INSERT INTO projects (name,location,description,image,completion) SELECT * FROM (VALUES
('Сосновый квартал','Москва, Сосновая улица','Дома у парка, где город становится ближе к природе.','https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=80','IV квартал 2027'),
('Река и город','Москва, набережная','Современный квартал у воды с уютными дворами и кафе.','https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=80','II квартал 2028'),
('Первый парк','Московская область','Пространство для жизни с зелёными аллеями и школой рядом.','https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80','Дом сдан')) AS v(name,location,description,image,completion) WHERE NOT EXISTS (SELECT 1 FROM projects);
INSERT INTO apartments (project_id,rooms,area,floor,price) SELECT p.id, a.rooms,a.area,a.floor,a.price FROM projects p CROSS JOIN (VALUES (0,26.5,4,7200000),(1,39.2,7,9800000),(2,58.4,12,14500000),(3,78.1,9,18900000)) a(rooms,area,floor,price) WHERE NOT EXISTS (SELECT 1 FROM apartments);
INSERT INTO news (title,body,published,image) SELECT * FROM (VALUES ('Новый квартал рядом с парком','Открываем продажи квартир в зелёном районе города.','2026-09-11'::date,'https://images.unsplash.com/photo-1600607687644-c7171b42498f?auto=format&fit=crop&w=900&q=80'),('Дворы для встреч и отдыха','Рассказываем, как создаём пространства для соседей.','2026-08-23'::date,'https://images.unsplash.com/photo-1511818966892-d7d671e672a2?auto=format&fit=crop&w=900&q=80'),('Школа рядом с домом','В новом квартале появятся школа и детский сад.','2026-07-21'::date,'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=900&q=80')) v(title,body,published,image) WHERE NOT EXISTS (SELECT 1 FROM news);
INSERT INTO mortgage_programs (name,rate,description) SELECT * FROM (VALUES ('Семейная',6.00,'Пример расчёта для семей с детьми'),('Базовая',18.00,'Пример стандартной ипотечной программы'),('Льготная',8.00,'Пример программы с пониженной ставкой')) v(name,rate,description) WHERE NOT EXISTS (SELECT 1 FROM mortgage_programs);
